        static Lang()
        {
            for (int i = 0; i < TBL.Length; i++)
            {
                string[] row = TBL[i];
                if (row == null || row.Length < 4) continue;
                PACK[row[0]] = new string[] { row[1], row[2], row[3] };
            }
        }

        /// <summary>从 ui.txt 读回上次选的语言。必须在 MainForm 构造之前调用。</summary>
        public static void Load()
        {
            try
            {
                string p = System.IO.Path.Combine(
                    System.IO.Path.GetDirectoryName(Application.ExecutablePath), "ui.txt");
                if (!System.IO.File.Exists(p)) return;
                foreach (string line in System.IO.File.ReadAllLines(p, Encoding.UTF8))
                {
                    string t = (line ?? "").Trim();
                    if (!t.StartsWith("lang=")) continue;
                    int v = 0;
                    if (int.TryParse(t.Substring(5).Trim(), out v) && v >= ZH && v <= ES) Id = v;
                    break;
                }
            }
            catch (Exception dg1174_1) { Diag.Swallow("Lang.cs:1174", dg1174_1); }
        }

        /// <summary>统一取词。中文直接返回；英文返回 en；法 / 俄 / 西查语言包，缺失回退英文。</summary>
        public static string T(string zh, string en)
        {
            if (Id == ZH) return zh;
            if (Id == EN) return en;
            string[] v = null;
            if (!PACK.TryGetValue(zh, out v)) return en;
            if (v != null)
            {
                string tv = v[Id == FR ? 0 : (Id == RU ? 1 : 2)];
                if (tv != null && tv.Length > 0) return tv;
            }
            return en;
        }
    }
